import { after } from 'next/server'
import { logPageView } from '@/app/utils'

export default function Home() {
  after(() => {
    // Runs after the response is sent so analytics does not block rendering.
    logPageView('/')
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting.</p>
    </main>
  )
}

